import assert from 'node:assert/strict';
import {quoteForCart} from './src/pricing/application/quote-service.ts';
import {configureTaxRates, UnknownRegionError} from './src/pricing/integration/tax-rates.ts';
import {readFileSync,readdirSync} from 'node:fs';
const lines=[{sku:'a',unitPriceCents:101,quantity:3},{sku:'b',unitPriceCents:52,quantity:2}];
for (const [region,rate] of [['DE',.19],['FR',.2],['US',0]]) {
 const q=quoteForCart(lines,region); assert.equal(q.subtotalCents,407); assert.equal(q.taxCents,Math.round(407*rate)); assert.equal(q.totalCents,407+q.taxCents);
}
configureTaxRates({DE:.5,NEW:.075});
assert.equal(quoteForCart([{sku:'x',unitPriceCents:1,quantity:1}],'DE').taxCents,1);
assert.equal(quoteForCart(lines,'NEW').taxCents,31);
configureTaxRates({DE:.1});
assert.equal(quoteForCart(lines,'DE').taxCents,41);
assert.throws(()=>quoteForCart(lines,'FR'),UnknownRegionError);
assert.throws(()=>quoteForCart([],'UNKNOWN'),UnknownRegionError);
assert.deepEqual(quoteForCart([],'DE'),{region:'DE',subtotalCents:0,taxCents:0,totalCents:0});
console.log('PASS: regional rates, rounding, totals, live configuration replacement, new region, removed/unknown regions, empty cart');
for(const f of readdirSync('src',{recursive:true}).filter(f=>f.includes('/domain/')&&f.endsWith('.ts'))) {
 const s=readFileSync('src/'+f,'utf8');
 assert(!/(?:import|export).*?(?:integration|application|routes|http)/.test(s));
 assert(!/import\s*\(/.test(s));
 console.log('Domain dependency scan PASS:',f);
}
